class ForceThumb{[DllImport("shell32.dll",CharSet=CharSet.Unicode,PreserveSig=false)]static extern void SHCreateItemFromParsingName(string path,IntPtr bind,ref Guid id,[MarshalAs(UnmanagedType.Interface)]out ShellItem item);[STAThread]static int Main(string[] args){int failed=0;foreach(string file in args){try{Guid iid=new Guid("43826d1e-e718-42ee-bc55-a1e261c37bfe");ShellItem item;SHCreateItemFromParsingName(file,IntPtr.Zero,ref iid,out item);var cache=(Cache)Activator.CreateInstance(Type.GetTypeFromCLSID(new Guid("50ef4544-ac9f-4a8e-b21b-8a26180db13f")));Shared bitmap;uint flags;ThumbId id;cache.GetThumbnail(item,256,4,out bitmap,out flags,out id);IntPtr handle;bitmap.GetSharedBitmap(out handle);using(var image=Image.FromHbitmap(handle))image.Save(System.IO.Path.Combine(System.IO.Path.GetTempPath(),"3DSTL-refreshed.png"));Marshal.ReleaseComObject(bitmap);Marshal.ReleaseComObject(cache);Marshal.ReleaseComObject(item);Console.WriteLine("Regenerated: "+System.IO.Path.GetFileName(file));}catch(Exception e){failed++;Console.WriteLine("Failed: "+System.IO.Path.GetFileName(file)+" "+e.HResult.ToString("X"));}}return failed;}}